var BS_SIZE=10, BS_FLEET=[5,4,3,3,2];
function bsPlace(){
  var board=new Array(BS_SIZE*BS_SIZE).fill(0), ships=[];
  BS_FLEET.forEach(function(sz){
    var placed=false, guard=0;
    while(!placed && guard<800){ guard++;
      var horiz=Math.random()<0.5; var r=Math.floor(Math.random()*BS_SIZE), c=Math.floor(Math.random()*BS_SIZE);
      var cells=[], ok=true;
      for(var i=0;i<sz;i++){ var rr=r+(horiz?0:i), cc=c+(horiz?i:0); if(rr<0||rr>=BS_SIZE||cc<0||cc>=BS_SIZE){ok=false;break;} if(board[rr*BS_SIZE+cc]===1){ok=false;break;} cells.push(rr*BS_SIZE+cc); }
      if(!ok) continue;
      cells.forEach(function(idx){ board[idx]=1; });
      ships.push({cells:cells.slice(), hits:new Array(sz).fill(false)}); placed=true;
    }
  });
  return {board:board, ships:ships};
}
function bsFire(state, r, c){
  var idx=r*BS_SIZE+c; if(state.board[idx]!==1) return {result:'miss', sunk:false};
  for(var s=0;s<state.ships.length;s++){ var ship=state.ships[s]; var ci=ship.cells.indexOf(idx); if(ci>=0){ if(ship.hits[ci]) return {result:'hit', sunk:false, already:true}; ship.hits[ci]=true; var sunk=ship.hits.every(function(h){return h;}); return {result:'hit', sunk:sunk}; } }
  return {result:'miss', sunk:false};
}
function bsAllSunk(state){ return state.ships.every(function(sh){return sh.hits.every(function(h){return h;});}); }
var EXPORTS={bsPlace:bsPlace,bsFire:bsFire,bsAllSunk:bsAllSunk,BS_SIZE:BS_SIZE,BS_FLEET:BS_FLEET};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BattleForgePure = EXPORTS; }
